describe("services/project-service", () => {
  it("refuses creation once the plan's project quota is reached", async () => {
    // `createTenant` already inserts one project, so the free plan's ceiling
    // of two projects is one `createProject` call away.
    const tenant = await createTenant("projquota", "free");

    await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Second Project", slug: "second", key: "SEC" }),
    );

    await expect(
      projectService.createProject(
        tenant.actors.member,
        projectInput(tenant.org.id, { name: "Third Project", slug: "third", key: "THI" }),
      ),
    ).rejects.toThrow(/allows 2 projects/);
  });

  it("suggests a suffixed slug when the requested one is taken", async () => {
    // `createTenant` seeds a project already slugged "platform".
    const tenant = await createTenant("projslug", "growth");
    expect(tenant.project.slug).toBe("platform");

    await expect(
      projectService.suggestProjectSlug(tenant.org.id, "Platform"),
    ).resolves.toBe("platform-2");
  });

  it("scopes slug uniqueness to the organization", async () => {
    const tenantA = await createTenant("slugorga", "growth");
    const tenantB = await createTenant("slugorgb", "growth");

    await projectService.createProject(
      tenantB.actors.member,
      projectInput(tenantB.org.id, { name: "Rocket", slug: "rocket", key: "ROC" }),
    );

    // "rocket" is taken in org B but free in org A.
    await expect(
      projectService.suggestProjectSlug(tenantA.org.id, "Rocket"),
    ).resolves.toBe("rocket");
  });

  it("cascades the archive to the project's issues when asked", async () => {
    const tenant = await createTenant("archivecascade", "growth");

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Live issue 1" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Live issue 2" }),
    );

    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(2);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: true,
    });

    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(0);
    expect(
      await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
        includeArchived: true,
      }),
    ).toBe(2);
  });

  it("emits project.archived with the number of issues archived", async () => {
    const tenant = await createTenant("archiveevent", "growth");

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "To be archived" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Also archived" }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Archived too" }),
    );

    const received: unknown[] = [];
    const off = subscribe("project.archived", (payload) => {
      received.push(payload);
    });

    try {
      const archived = await projectService.archiveProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        archiveIssues: true,
      });

      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({ projectId: archived.id, issuesArchived: 3 });
    } finally {
      off();
    }
  });

  it("restores an archived project and emits project.restored", async () => {
    const tenant = await createTenant("restoreproj", "growth");

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    const received: unknown[] = [];
    const off = subscribe("project.restored", (payload) => {
      received.push(payload);
    });

    try {
      const restored = await projectService.restoreProject(
        tenant.actors.admin,
        tenant.org.id,
        tenant.project.id,
      );

      expect(restored.archivedAt).toBeNull();

      const stored = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
      expect(stored?.archivedAt).toBeNull();

      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({ projectId: tenant.project.id });
    } finally {
      off();
    }
  });
});

/**
 * The `organization_usage` counters read by every plan-limit check.
 */
import { and, count, eq, isNull, sql } from "drizzle-orm";
import {
  attachments,
  getDb,
  issues,
  members,
  organizationUsage,
  projects,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUsage } from "./_mappers";
import { brandId } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { OrganizationUsage } from "@/types/organization";

const BYTES_PER_MB = 1024 * 1024;

/**
 * Reads the cached counters, materialising a zeroed row the first time an org
 * is asked about. A limit check must never fail because the rollup has not run.
 */
export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
  const row = getDb()
    .select()
    .from(organizationUsage)
    .where(eq(organizationUsage.orgId, orgId))
    .get();

  if (row) return toUsage(row);

  const created = getDb()
    .insert(organizationUsage)
    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
    .returning()
    .get();

  return toUsage(created);
}

/**
 * Recounts every dimension from the source tables and rewrites the cache.
 * Called by the rollup job and after any bulk change that would drift.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const db = getDb();

  const seats = db
    .select({ value: count() })
    .from(members)
    .where(
      and(
        eq(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .get();

  const projectCount = db
    .select({ value: count() })
    .from(projects)
    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
    .get();

  const issueCount = db
    .select({ value: count() })
    .from(issues)
    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
    .get();

  const bytes = db
    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
    .from(attachments)
    .where(eq(attachments.orgId, orgId))
    .get();

  const next = {
    orgId,
    seatsUsed: seats?.value ?? 0,
    projectsUsed: projectCount?.value ?? 0,
    issuesUsed: issueCount?.value ?? 0,
    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
    measuredAt: toIsoTimestamp(new Date()),
  };

  const row = db
    .insert(organizationUsage)
    .values(next)
    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
    .returning()
    .get();

  return toUsage(row);
}

/**
 * Cheap delta applied on the write path so a quota check right after a create
 * sees the new number without waiting for the rollup.
 */
export async function incrementUsage(
  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
      measuredAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

/** The rollup job's work list: the oldest measurements first. */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizationUsage.orgId })
    .from(organizationUsage)
    .orderBy(organizationUsage.measuredAt)
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

/**
 * Private paging helpers shared by the repositories in this directory.
 *
 * Not part of the public data-access surface — repositories re-export nothing
 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
 * so a page boundary is stable even when two rows share a `created_at`.
 */
import { sql } from "drizzle-orm";
import { decodeCursor, encodeCursor } from "./base-repository";
import { makePage } from "@/types/common";
import type { Page } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

export interface KeysetSort {
  readonly sortColumn: SQLiteColumn;
  readonly idColumn: SQLiteColumn;
}

/**
 * Predicate that resumes a descending listing after `cursor`. Returns
 * `undefined` for a first page or an unparseable cursor — a bad cursor
 * degrades to "start from the top", never to an error page.
 */
export function keysetPredicate(
  sort: KeysetSort,
  cursor: string | null | undefined,
): SQL | undefined {
  if (!cursor) return undefined;
  const decoded = decodeCursor(cursor);
  if (!decoded) return undefined;

  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
}

/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
export function probeLimit(limit: number): number {
  return Math.max(1, Math.min(limit, 100)) + 1;
}

/**
 * Turns an over-fetched row array into a `Page`, dropping the probe row and
 * deriving the next cursor from the last row that survived.
 */
export function toPage<TRow, TOut>(
  rows: readonly TRow[],
  limit: number,
  total: number,
  map: (row: TRow) => TOut,
  cursorOf: (row: TRow) => { id: string; sortValue: string },
): Page<TOut> {
  const capped = Math.max(1, Math.min(limit, 100));
  const hasMore = rows.length > capped;
  const visible = hasMore ? rows.slice(0, capped) : rows;
  const last = visible.at(-1);

  const nextCursor =
    hasMore && last
      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
      : null;

  return makePage(visible.map(map), nextCursor, total);
}

/** Drops the `undefined` slots so `and(...)` never sees a hole. */
export function compact(
  ...predicates: readonly (SQL | undefined)[]
): readonly SQL[] {
  return predicates.filter((value): value is SQL => value !== undefined);
}

